for key, (path, caption) in images.items():
    page = page.replace('@@'+key+'@@', image(path, caption))
names = ['阿安','安母','果行卖者','顾嫂','沈客','何四','船工','老周','许娘子','修篓人','阿绣','戏班搭档','铺兵']
