assert not re.search(r'@@\w+@@', page)
OUTPUT.write_text(page, encoding='utf-8')
print(f'Created: {OUTPUT.name}; images={len(images)}; size={OUTPUT.stat().st_size / 1024 / 1024:.1f} MB')
